# -*- coding: utf-8 --

import time
from robot.api import logger
import json
from taf.rfrl.cbts.connections.rest_conn_vdu import GenericVDU
from taf.internal.robot_typecasts.typecasts import time_to_seconds

LOG_HEAD = LOG_END = '*' * 8


class vDUCM(GenericVDU):

    # ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def _perform_delta_recommissioning(self, delta_file, timeout=300, connection=None):
        return self.vdu.perform_delta_recommissioning(delta_file=delta_file, wait_for_completion=True,
                                                      should_activate=True, timeout=timeout, vdu_connection=connection)

    def full_commissioning(self, stage_plan_file_path, plan_name="default_plan_name",
                           conn_alias='default', timeout_4_full_commission_finished=300):
        upload_plan_act_id = self.vdu.upload_plan(path_to_plan_file=stage_plan_file_path, plan_name=plan_name,
                                                  vdu_connection=conn_alias)['action_id']
        stage_plan_id = self._verify_upload_stage_plan_action_status(upload_plan_act_id,
                                                                     conn_alias=conn_alias,
                                                                     timeout=30)
        validate_plan_act_id = self.vdu.validate_plan(plan_id=stage_plan_id, vdu_connection=conn_alias)['action_id']
        self._verify_validate_stage_plan_action_status(action_id=validate_plan_act_id, plan_id=stage_plan_id,
                                                       conn_alias=conn_alias,
                                                       timeout=30)
        activate_plan_act_id = self.vdu.activate_plan(plan_id=stage_plan_id,
                                                      vdu_connection=conn_alias)['id']
        self._verify_activate_stage_plan_action_status(action_id=activate_plan_act_id,
                                                       plan_id=stage_plan_id,
                                                       conn_alias=conn_alias,
                                                       timeout=time_to_seconds(timeout_4_full_commission_finished))
        # time.sleep(30)

    def _verify_upload_stage_plan_action_status(self, action_id, expected_status='success', conn_alias='default',
                                                timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            upload_stage_plan_res = self.vdu.get_upload_plan_operation_status(operation_id=action_id,
                                                                              vdu_connection=conn_alias)
            if upload_stage_plan_res['status'] == expected_status:
                logger.info('{} Stage plan was uploaded successfully {}'.format(LOG_HEAD, LOG_END))
                return upload_stage_plan_res['plan_id']
            else:
                time.sleep(2)
        raise Exception('Uploading stage plan failed in the given 20s. The status is {}, error msg is {}'.format(
            upload_stage_plan_res['status'], upload_stage_plan_res['error_message']
        ))

    def _verify_validate_stage_plan_action_status(self, action_id, plan_id, expected_status='success',
                                                  conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            val_stage_plan_res = self.vdu.get_validate_plan_operation_status(plan_id=plan_id,
                                                                             operation_id=action_id,
                                                                             vdu_connection=conn_alias)
            if val_stage_plan_res['status'] == expected_status:
                logger.info('{} Stage plan was validated successfully {}'.format(LOG_HEAD, LOG_END))
                return
            else:
                time.sleep(2)
        raise Exception('Validating stage plan failed in the given 20s. The status is {}, error msg is {}'.format(
            val_stage_plan_res['status'], val_stage_plan_res['error_message']
        ))

    def _verify_activate_stage_plan_action_status(self, action_id, plan_id,
                                                  conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            try:
                activate_stage_plan_res = self.vdu.get_activate_plan_operation_status(plan_id=plan_id,
                                                                                      operation_id=action_id,
                                                                                      vdu_connection=conn_alias)
                if activate_stage_plan_res['status'] == 'success':
                    logger.info('{} Stage plan was activated successfully {}'.format(LOG_HEAD, LOG_END))
                    return
                elif activate_stage_plan_res['status'] == 'failure':
                    raise Exception('{} Stage Plan was activated Failed {}\n{}'.format(LOG_HEAD, LOG_END,
                                                                                       activate_stage_plan_res))
                else:
                    logger.info('{} Activating Stage plan in ongoing {}'.format(LOG_HEAD, LOG_END))
                    time.sleep(2)
            except Exception as err:
                if "service unavailable" or "connection refused" in str(err).lower():
                    logger.info(
                        '{} UM service is not available or Connection refused due to NE reset, '
                        'will retry in 2min {}'.format(LOG_HEAD, LOG_END))
                else:
                    logger.info('{} Get provision delta plan status failure {}'.format(LOG_HEAD, LOG_END))
                    logger.info(str(err))
                time.sleep(120)

        raise Exception('Activating stage plan failed in the given time. The status is {}, error msg is {}'.format(
            activate_stage_plan_res['status'], activate_stage_plan_res['error_message']))

    def _validate_gen_delta_plan_status(self, action_id, conn_alias='default', timeout=15):
        endtime = time.time() + timeout
        while time.time() < endtime:
            gen_delta_plan_res = self.vdu.get_delta_plan_generated_action_status(action_id=action_id,
                                                                                 vdu_connection=conn_alias)
            if gen_delta_plan_res['status'] == 'success':
                logger.info('{} Delta plan created successfully {}'.format(LOG_HEAD, LOG_END))
                return gen_delta_plan_res['plan_id']
            else:
                time.sleep(2)
        raise Exception('Generating Delta plan failed in the given 15s. The status is {}, error msg is {}'.format(
            gen_delta_plan_res['status'], gen_delta_plan_res['error_message']
        ))

    def _provision_vdu_delta_plan(self, operation_id, use_m2m=True, conn_alias='default', timeout=300):
        endtime = time.time() + timeout
        while time.time() < endtime:
            try:
                pro_delta_plan_info = self.vdu.get_provision_vdu_delta_plan_status(operation_id=operation_id,
                                                                                   use_m2m=use_m2m,
                                                                                   vdu_connection=conn_alias)
                pro_delta_plan_status = pro_delta_plan_info['status']
                if pro_delta_plan_status == 'success':
                    logger.info('{} Delta plan provisioned successfully {}'.format(LOG_HEAD, LOG_END))
                    return
                elif pro_delta_plan_status == 'failure':
                    raise Exception('{} Activating delta Plan Failure {}\n{}'.format(LOG_HEAD, LOG_END,
                                                                                     pro_delta_plan_info))
                else:
                    logger.info('{} Provision delta plan is ongoing {}'.format(LOG_HEAD, LOG_END))
                    time.sleep(2)
            except Exception as err:
                if "service unavailable" or "connection refused" in str(err).lower():
                    logger.info(
                        '{} UM service is not available or Connection refused due to NE reset, '
                        'will retry in 2min {}'.format(LOG_HEAD, LOG_END))
                else:
                    logger.info('{} Get provision delta plan status failure {}'.format(LOG_HEAD, LOG_END))
                    logger.info(str(err))
                time.sleep(120)
        raise Exception('Delta commissioning failed in the given 300s. The status is {}'.format(pro_delta_plan_info))

    def fast_delta_commissioning(self, delta_data, use_m2m=True, conn_alias='default',
                                 timeout_4_provision_finished=300):
        pro_delta_ope_id = self.vdu.provision_vdu_delta_plan(mo_info_list=delta_data,
                                                             use_m2m=use_m2m,
                                                             vdu_connection=conn_alias)['id']
        self._provision_vdu_delta_plan(operation_id=pro_delta_ope_id, use_m2m=use_m2m,
                                       conn_alias=conn_alias,
                                       timeout=time_to_seconds(timeout_4_provision_finished))

    def generate_dela_plan_file(self, delta_plan_name='DELTA-PLAN-1', conn_alias='default',
                                timeout_4_rest_ope_finished=30):
        delta_plan_list = self.vdu.get_delta_plan_info_list(vdu_connection=conn_alias)
        if len(delta_plan_list) == 1:
            self.vdu.delete_delta_plan_file(plan_id=delta_plan_list[0]['plan_id'], vdu_connection=conn_alias)
            logger.info('{} Delta plan is already existed in the current vdu, it was deleted successfully {}'.format(
                LOG_HEAD, LOG_END))
            if len(self.vdu.get_delta_plan_info_list(vdu_connection=conn_alias)) != 0:
                raise Exception('Deleting delta plan failed')
        gen_delta_act_id = self.vdu.generate_delta_plan(plan_name=delta_plan_name,
                                                        vdu_connection=conn_alias)['action_id']
        delta_plan_id = self._validate_gen_delta_plan_status(action_id=gen_delta_act_id, conn_alias=conn_alias,
                                                             timeout=time_to_seconds(timeout_4_rest_ope_finished))
        return delta_plan_id

    def _verify_create_vdu_deltaplan_mo_status(self, action_id, plan_id, expect_status='success',
                                               conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            status = self.vdu.get_create_vdu_object_action_status_of_delta_plan(action_id=action_id,
                                                                                plan_id=plan_id,
                                                                                vdu_connection=conn_alias)['status']
            if status == expect_status:
                logger.info('{} The status of create vdu MO for delta plan is as expected - {} {}'.format(
                    LOG_HEAD, expect_status, LOG_END))
                return
            else:
                time.sleep(2)
        raise Exception(
            'The status of create vdu MO for delta plan not match the expected. The real status is {}'.format(status))

    def create_managed_object_for_delta_plan(self, parent_mo_dn, mo_name, conn_alias='default',
                                             timeout_4_rest_ope_finished=30):
        delta_plan_id = self.vdu.get_delta_plan_info_list(vdu_connection=conn_alias)[0]['plan_id']
        create_mo_res = self.vdu.create_vdu_object_of_delta_plan(delta_plan_id=delta_plan_id,
                                                                 parent_mo_dn=parent_mo_dn,
                                                                 mo_name=mo_name,
                                                                 vdu_connection=conn_alias)
        self._verify_create_vdu_deltaplan_mo_status(action_id=create_mo_res['action_id'],
                                                    plan_id=delta_plan_id,
                                                    conn_alias=conn_alias,
                                                    timeout=time_to_seconds(timeout_4_rest_ope_finished))

    def update_parameter_for_delta_plan(self, mo_dn, delta_param_dict, operation='replace',
                                        expect_status='success', conn_alias='default', timeout_4_rest_ope_finished=30):
        delta_plan_id = self.vdu.get_delta_plan_info_list(vdu_connection=conn_alias)[0]['plan_id']
        update_para_act_id = self.vdu.update_vdu_parameter_of_delta_plan(plan_id=delta_plan_id,
                                                                         mo_dn=mo_dn,
                                                                         updated_paras_dict=delta_param_dict,
                                                                         operation=operation,
                                                                         vdu_connection=conn_alias)['action_id']
        self._verify_update_param_for_vdu_delta_plan_action(action_id=update_para_act_id,
                                                            plan_id=delta_plan_id,
                                                            expect_status=expect_status,
                                                            conn_alias=conn_alias,
                                                            timeout=time_to_seconds(timeout_4_rest_ope_finished))

    def _verify_update_param_for_vdu_delta_plan_action(self, action_id, plan_id, expect_status='success',
                                                       conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            res = self.vdu.get_update_paras_action_status_of_delta_plan(action_id=action_id,
                                                                        plan_id=plan_id,
                                                                        vdu_connection=conn_alias)
            if res['status'] == expect_status:
                logger.info(
                    '{} The action status of updating vdu parameter for delta plan is as expected - {} {}'.format(
                        LOG_HEAD, expect_status, LOG_END))
                return
            else:
                time.sleep(2)
        raise Exception(
            'The real status is {} which does not match the expected. Error message is {}'.format(
                res['status'], res.get('error_message', '')))

    def validate_delta_plan(self, expect_status='success', conn_alias='default', timeout_4_rest_ope_finished=30):
        delta_plan_id = self.vdu.get_delta_plan_info_list(vdu_connection=conn_alias)[0]['plan_id']
        validate_act_id = self.vdu.validate_delta_plan(delta_plan_id=delta_plan_id,
                                                       vdu_connection=conn_alias)['action_id']
        # TODO: fixing validation error can be added, using try ... expect ...
        validation_id = self._verify_validate_vdu_delta_plan_action(
            delta_plan_id=delta_plan_id,
            action_id=validate_act_id,
            expect_status=expect_status,
            conn_alias=conn_alias,
            timeout=time_to_seconds(timeout_4_rest_ope_finished)
        )
        endtime = time.time() + timeout_4_rest_ope_finished
        while time.time() < endtime:
            try:
                validation_result = self.vdu.get_delta_plan_validation_results(
                    plan_id=delta_plan_id,
                    validation_id=validation_id,
                    vdu_connection=conn_alias
                )
                logger.info('{} The validation result of delta plan is: {}'.format(LOG_HEAD, validation_result))
                return
            except Exception:
                time.sleep(2)
        logger.error(
            '{} Can not get the validation result for the delta plan in the give time {}'.format(
                LOG_HEAD, timeout_4_rest_ope_finished)
        )

    def activate_delta_plan(self, force_reset=True, auto_lock_cells=True,
                            conn_alias='default', timeout_4_rest_ope_finished=300):
        delta_plan_id = self.vdu.get_delta_plan_info_list(vdu_connection=conn_alias)[0]['plan_id']
        activate_act_id = self.vdu.activate_delta_plan(delta_plan_id=delta_plan_id,
                                                       force_reset=force_reset,
                                                       auto_lock_cells=auto_lock_cells,
                                                       vdu_connection=conn_alias)['id']
        self._verify_activate_vdu_delta_plan_action(delta_plan_id, activate_act_id,
                                                    conn_alias=conn_alias,
                                                    timeout=time_to_seconds(timeout_4_rest_ope_finished))

    def _verify_validate_vdu_delta_plan_action(self, delta_plan_id, action_id, expect_status='success',
                                               conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            validation_result = self.vdu.get_validate_delta_plan_operation_status(delta_plan_id=delta_plan_id,
                                                                                  action_id=action_id,
                                                                                  vdu_connection=conn_alias)
            if validation_result['status'] == expect_status:
                logger.info('{} The action status of validating vdu delta plan is as expected - {} {}'.format(
                    LOG_HEAD, expect_status, LOG_END))
                return validation_result['validation_id']
            else:
                time.sleep(1)
        raise Exception(
            'The status of validating delta plan not matched the expected status. '
            'The real status is {}'.format(validation_result['status'])
        )

    def _verify_activate_vdu_delta_plan_action(self, delta_plan_id, action_id, conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            try:
                act_delta_plan_info = self.vdu.get_activate_delta_plan_operation_status(delta_plan_id=delta_plan_id,
                                                                                        operation_id=action_id,
                                                                                        vdu_connection=conn_alias)
                act_delta_plan_status = act_delta_plan_info['status']
                if act_delta_plan_status == 'success':
                    logger.info('{} Delta plan is activated successfully {}'.format(LOG_HEAD, LOG_END))
                    return
                elif act_delta_plan_status == 'failure':
                    raise Exception('{} Activating delta Plan Failure {}\n{}'.format(LOG_HEAD, LOG_END,
                                                                                     act_delta_plan_status))
                else:
                    logger.info('{} Activating delta plan is ongoing {}'.format(LOG_HEAD, LOG_END))
                    time.sleep(2)
            except Exception as err:
                if "service unavailable" or "connection refused" in str(err).lower():
                    logger.info(
                        '{} UM service is not available or Connection refused due to NE reset, '
                        'will retry in 2min {}'.format(LOG_HEAD, LOG_END))
                else:
                    logger.info('{} Get activating delta plan status failure {}'.format(LOG_HEAD, LOG_END))
                    logger.info(str(err))
                time.sleep(120)

        raise Exception(
            'The action status of activating vdu delta plan is not successful in 5min. The status is {}'.format(status))

    def get_parameter_value_from_current_plan(self, mo_dn, parameter_name, conn_alias='default'):
        return self.vdu.search_parameter_of_current_plan(mo_dn=mo_dn,
                                                         para_name=parameter_name,
                                                         vdu_connection=conn_alias)

    def fast_activate_delta_plan_internal_api(self, dist_name, param_value_dict, operation='update',
                                              conn_alias='default', timeout_4_rest_ope_finished=30):
        class_name = dist_name.split('/')[-1].split('-')[0]
        ope_id = self.vdu.fast_activations_for_delta_plan(class_name=class_name,
                                                          dist_name=dist_name,
                                                          payload=json.dumps(param_value_dict),
                                                          operation=operation,
                                                          vdu_connection=conn_alias)['id']
        self._verify_vdu_fast_activation_status(operation_id=ope_id, conn_alias=conn_alias,
                                                timeout=time_to_seconds(timeout_4_rest_ope_finished))

    def _verify_vdu_fast_activation_status(self, operation_id, conn_alias='default', timeout=30):
        endtime = time.time() + timeout
        while time.time() < endtime:
            pro_delta_plan_status = self.vdu.get_fast_activation_operation_of_delta_plan(operation_id=operation_id,
                                                                                         vdu_connection=conn_alias)[
                'status']
            if pro_delta_plan_status == 'success':
                logger.info('{} Fast activating Delta plan is successful {}'.format(LOG_HEAD, LOG_END))
                return
            else:
                time.sleep(2)
        raise Exception('Delta commissioning failed in the given 300s. The status is {}'.format(
            pro_delta_plan_status))

    def get_mo_parameters_of_current_plan(self, dist_name, conn_alias='default'):
        return self.vdu.get_managed_object_parameters_of_current_plan(dist_name=dist_name, vdu_connection=conn_alias)

    def get_complex_parameter_maxoccurs_from_nidd(self, class_name, param_name, conn_alias='default'):
        nidd_info = self.vdu.get_nidd(vdu_connection=conn_alias)
        mo = list(filter(lambda x: x['class_name'] == class_name, nidd_info))
        params = mo[0]['parameters']
        for p_name, p_def in params.items():
            if p_name == param_name:
                try:
                    return int(p_def["complex_parameter_def"]["max_occurs"])
                except KeyError:
                    return int(p_def["simple_list_parameter_def"]["max_occurs"])
        raise Exception('Can not find the parameter {} under {}'.format(param_name, class_name))
